// SessionServiceHandler is an implementation of the jingclaw.control.v1.SessionService service.
type SessionServiceHandler interface {
	CreateSession(context.Context, *connect.Request[v1.CreateSessionRequest]) (*connect.Response[v1.CreateSessionResponse], error)
	// ListSessions is how a client that did not start a session finds it.
	//
	// A run outlives the client that began it, so a second client — the web
	// console, a GUI attaching later — has to be able to discover what is going
	// on without having been there.
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	ListRuns(context.Context, *connect.Request[v1.ListRunsRequest]) (*connect.Response[v1.ListRunsResponse], error)
	// GetSessionView is the state of a session now, without replaying it.
	//
	// A client attaching to a long session would otherwise read every event
	// from the beginning to work out what is on the screen — which is correct
	// and gets slower every turn, until opening a conversation somebody has
	// been using for a week is a visible wait. This gives the answer directly,
	// and a sequence number to subscribe from so nothing between the two is
	// missed.
	GetSessionView(context.Context, *connect.Request[v1.GetSessionViewRequest]) (*connect.Response[v1.GetSessionViewResponse], error)
	SendTurn(context.Context, *connect.Request[v1.SendTurnRequest]) (*connect.Response[v1.SendTurnResponse], error)
	SubscribeEvents(context.Context, *connect.Request[v1.SubscribeEventsRequest], *connect.ServerStream[v1.SubscribeEventsResponse]) error
	SubscribeAllEvents(context.Context, *connect.Request[v1.SubscribeAllEventsRequest], *connect.ServerStream[v1.SubscribeAllEventsResponse]) error
	InterruptRun(context.Context, *connect.Request[v1.InterruptRunRequest]) (*connect.Response[v1.InterruptRunResponse], error)
	ListApprovals(context.Context, *connect.Request[v1.ListApprovalsRequest]) (*connect.Response[v1.ListApprovalsResponse], error)
	DecideApproval(context.Context, *connect.Request[v1.DecideApprovalRequest]) (*connect.Response[v1.DecideApprovalResponse], error)
	// ListQuestions is what the agent has asked and nobody has answered.
	ListQuestions(context.Context, *connect.Request[v1.ListQuestionsRequest]) (*connect.Response[v1.ListQuestionsResponse], error)
	// AnswerQuestion unblocks a run that stopped to ask.
	AnswerQuestion(context.Context, *connect.Request[v1.AnswerQuestionRequest]) (*connect.Response[v1.AnswerQuestionResponse], error)
	// ListModels is what this daemon's provider offers, and which one a session
	// is using.
	//
	// Asked of the provider rather than read from a list here: a local server
	// has whatever somebody pulled onto that machine, and a catalogue written
	// here would be wrong on every deployment that is not this one.
	ListModels(context.Context, *connect.Request[v1.ListModelsRequest]) (*connect.Response[v1.ListModelsResponse], error)
	// SetSessionModel chooses which model answers in a session.
	//
	// The next run picks it up. A run already generating has a request open
	// with a model in it, and changing that underneath would attribute a turn
	// to a model that did not write it.
	SetSessionModel(context.Context, *connect.Request[v1.SetSessionModelRequest]) (*connect.Response[v1.SetSessionModelResponse], error)
}

